using System; using System.Reflection; using UnityEngine; using Golfin.Physics.Viewer;
public class Script {
    public static string Main() {
        var ctrl = UnityEngine.Object.FindObjectOfType<PhysicsLabController>(true);
        if (ctrl == null) return "No PhysicsLabController found";
        var scene = typeof(PhysicsLabController).GetField("currentScene", BindingFlags.NonPublic | BindingFlags.Instance);
        var lookDir = typeof(PhysicsLabController).GetField("_defaultLookDirection", BindingFlags.NonPublic | BindingFlags.Instance);
        var yaw = typeof(PhysicsLabController).GetField("_cameraYaw", BindingFlags.NonPublic | BindingFlags.Instance);
        return $"currentScene={scene?.GetValue(ctrl)} _defaultLookDirection={lookDir?.GetValue(ctrl)} _cameraYaw={yaw?.GetValue(ctrl)}";
    }
}
